// Kanji tracing strokes, from KanjiVG (https://github.com/KanjiVG/kanjivg, © Ulrich Apel,
// CC BY-SA 3.0). The stroke data itself is big (kanjiStrokes.data.ts, generated by
// scripts/build-kanji-strokes.mjs), so it isn't part of the app's main code: kanjiLoad.ts loads it
// when a lesson traces kanji and hands it to addKanjiStrokes; from then on letterGuide() finds
// kanji synchronously like letters and kana. Tests and the course checker import the data file
// directly. Which kanji can be traced is known without the data (kanjiList.ts), so lessons are
// checked the same way before and after it loads.

import { TRACE_KANJI } from "./kanjiList";

/** Strokes of the loaded kanji, still compact (see kanjiStrokes.data.ts). */
let loaded: Record<string, string> | null = null;
const known = new Set<string>();

/** Whether `ch` is a kanji that has tracing data (loaded or not). */
export function isTraceKanji(ch: string): boolean {
  if (!known.size) for (const c of TRACE_KANJI) known.add(c);
  return known.has(ch);
}

/** Makes the kanji data available to letterGuide(). */
export function addKanjiStrokes(data: Record<string, string>): void {
  loaded = data;
}

export const kanjiStrokesLoaded = () => loaded !== null;

/** One compact stroke ("x y" then six offsets per cubic) as absolute app commands. */
export function expandStroke(compact: string): string {
  const n = compact.trim().split(/\s+/).map(Number);
  if (n.length < 8 || (n.length - 2) % 6 || n.some((v) => !Number.isFinite(v))) throw new Error(`bad kanji stroke "${compact.slice(0, 20)}"`);
  let [x, y] = n;
  const out = [`M ${x} ${y}`];
  for (let i = 2; i < n.length; i += 6) {
    out.push(`C ${x + n[i]} ${y + n[i + 1]} ${x + n[i + 2]} ${y + n[i + 3]} ${x + n[i + 4]} ${y + n[i + 5]}`);
    x += n[i + 4];
    y += n[i + 5];
  }
  return out.join(" ");
}

/** Stroke commands for a kanji, in writing order, or undefined (not a traceable kanji, or the
 * data isn't loaded yet). */
export function kanjiStrokes(ch: string): string[] | undefined {
  const s = loaded?.[ch];
  return s ? s.split(";").map(expandStroke) : undefined;
}
